importArticles({
    type: 'script',
    articles: [
        'u:dev:MediaWiki:BackToTopButton/code.js',
    ]
});
window.BackToTopText = "Вгору";

/** Розміщений тут CSS буде застосовуватися до всіх тем оформлення */
a[href$="/HIHRAIM"],
a[href$=":HIHRAIM"] {
    color: #a351f5;
}

a[href$=":HIHRAIM"] ~ .EntityHeader_middot__2f4XC:after {
    content: "Шаман";
    background: #b90ddb;
    padding: 3px;
    border-radius: 5px;
    margin-left:4px;
    font-size: 12px;
    color: #ffffff;
}

a[href$="/Banette Bot"],
a[href$=":Banette Bot"] {
    color: #a351f5;
}

a[href$=":Banette Bot"] ~ .EntityHeader_middot__2f4XC:after {
    content: "Бот";
    background: #00FFFF;
    padding: 3px;
    border-radius: 5px;
    margin-left:4px;
    font-size: 12px;
    color: #ffffff;
}

.card {
	border: 2px solid var(--theme-border-color);
	box-sizing: border-box;
	display: flex;
	flex-direction: column;
	height: 120px;
	margin: 5px;
	padding: 5px;
	width: 120px;
}
.card:hover {
	background: var(--theme-accent-color);
}
.card a {
	font-weight: bold;
}
.card:hover a {
    color: var(--theme-accent-label-color);
}
.card img {
	height: 80px;
	object-fit: cover;
	width: 100%;
}

.tabber .wds-tabs {
    justify-content: center;
}

.tabber .wds-tabs__tab.wds-is-current {
	background-color: var(--theme-accent-color);
}

.tabber .wds-tabs__tab a:focus {
	color: #fff;
    text-decoration: none;
}

