/* === Скролбар (полоса прокрутки. Змінений скрипт BalancedScrollbar) === */
::-webkit-scrollbar {
  width: 10px;
}
::-webkit-scrollbar-track {
  background: var(--theme-page-background-color--secondary);
}
::-webkit-scrollbar-thumb {
  background:#bacdd8;
}
::-webkit-scrollbar-thumb:hover {
  background:#bacdd8;
}

/* ==== Firefox ==== */
:root {
  scrollbar-color:#bacdd8 var(--theme-page-background-color--secondary);
  scrollbar-width: thin;
}

