/* == Для статусників == */
/* === HIHRAIM === */
/* ==== Кольоровий нік ==== */
a[href$="/HIHRAIM"],
a[href$=":HIHRAIM"] {
    color: #a351f5;
}

/* ==== Коментарі ==== */
a[href$=":HIHRAIM"] ~ .EntityHeader_middot__2f4XC:after {
    content: "Шаман";
    background: #b90ddb;
    padding: 3px;
    border-radius: 5px;
    margin-left:4px;
    font-size: 12px;
    color: #ffffff;
}

/* === Banette Bot === */
/* ==== Кольоровий нік ==== */
a[href$="/Banette Bot"],
a[href$=":Banette Bot"] {
    color: #a351f5;
}

/* ==== Коментарі ==== */
a[href$=":Banette Bot"] ~ .EntityHeader_middot__2f4XC:after {
    content: "Бот";
    background: #00FFFF;
    padding: 3px;
    border-radius: 5px;
    margin-left:4px;
    font-size: 12px;
    color: #ffffff;
}

/* == Оформлення вікі == */
/* === Додавання прапорів до інтервіків (зроблено з InterlanguageFlags) === */
/* ==== RU (Русский) ==== */
.interwiki-ru::before,
.page-header__languages ul li a:is([data-tracking-label="lang-ru"], [data-tracking-label="lang-ru-GP"], [data-tracking-label="lang-ru-FD"])::before,
.page-footer__languages a:is([data-tracking-label="lang-ru"], [data-tracking-label="lang-ru-GP"], [data-tracking-label="lang-ru-FD"])::before {
	content: url("https://upload.wikimedia.org/wikipedia/commons/thumb/6/6f/White-blue-white_flag.svg/20px-White-blue-white_flag.svg.png") !important;
	padding-right: 8px;
}

/* === Кард === */
.card {
	border: 2px solid var(--theme-border-color);
	box-sizing: border-box;
	display: flex;
	flex-direction: column;
	height: 120px;
	margin: 5px;
	padding: 5px;
	width: 120px;
}
.card:hover {
	background: var(--theme-accent-color);
}
.card a {
	font-weight: bold;
}
.card:hover a {
    color: var(--theme-accent-label-color);
}
.card img {
	height: 80px;
	object-fit: cover;
	width: 100%;
}

/* === Таббери === */
.tabber .wds-tabs {
    justify-content: center;
}

.tabber .wds-tabs__tab.wds-is-current {
	background-color: var(--theme-accent-color);
}

.tabber .wds-tabs__tab a:focus {
	color: #fff;
    text-decoration: none;
}

/* === Скролбар (полоса прокрутки. Змінений скрипт BalancedScrollbar) === */
::-webkit-scrollbar {
  width: 10px;
}
::-webkit-scrollbar-track {
  background: var(--theme-page-background-color--secondary);
}
::-webkit-scrollbar-thumb {
  background:var(--theme-accent-color);
}
::-webkit-scrollbar-thumb:hover {
  background:var(--theme-accent-color);
}

/* ==== Firefox ==== */
:root {
  scrollbar-color:var(--theme-accent-color) var(--theme-page-background-color--secondary);
  scrollbar-width: thin;
}

/* === Видалення іконок === */
/* ==== Більшість блоків у рейці ==== */
.rail-module__header .wds-icon {
    display: none;
}

/* ==== Нові зображення, рейка ==== */
.rail-module h2.has-icon svg {
	display: none;
}

/* ==== Зміст, стаття ==== */
.toc .toctitle h2 .wds-icon + .wds-icon {
  display: none;
}

/* === Підсвічування синтаксисів (змінений скрипт SolarizedSyntaxHighlight) === */
.page pre {
	border: 2px solid #0004;
	padding: 8px 12px;
	max-width: 100%;
	line-height: 1.2em;
	-webkit-overflow-scrolling: touch;
}

.page .mw-highlight pre {
	color:#839496;
}

.theme-fandomdesktop-light .mw-highlight pre {
	background-color:#ffffff;
}

.theme-fandomdesktop-dark .mw-highlight pre {
	background-color:#2f2f2f;
}

/* ==== SYNTAX HIGHLIGHTING ==== */
/* ===== HTML & CSS ===== */
.mediawiki .mw-highlight .p  {color:#93a1a1;} /* punctuation CSS . # : { : ; } ( , ) HTML < / > */
.mediawiki .mw-highlight .o  {color:#93a1a1;} /* punctuation CSS -- ( : ) [ = ] HTML = */
.mediawiki .mw-highlight .c  {color:#586e75;font-style:italic;} /* HTML/CSS comment    */
.mediawiki .mw-highlight .cp {color:#dc322f;} /* CSS !important  HTML <!DOCTYPE>       */
.mediawiki .mw-highlight .nt {color:#268bd2;font-weight:bold;} /* html tag name (body, div), after @-rule*/

/* ===== HTML ===== */
.mediawiki .mw-highlight .na {color:#6c71c4;} /* attribute (id, class,...)    */
.mediawiki .mw-highlight .s  {color:#2aa198;} /* attribute "value"            */
.mediawiki .mw-highlight .ni {color:#b58900;} /* special character (&...;)    */

/* ===== CSS ===== */
.mediawiki .mw-highlight .n  {color:#93a1a1;} /* unrecognized syntax          */
.mediawiki .mw-highlight .nn {color:#d33682;text-shadow:0 0 #d33682;} /* id   */
.mediawiki .mw-highlight .nc {color:#6c71c4;} /* class                        */
.mediawiki .mw-highlight .nd {color:#268bd2;} /* pseudo-class (hover, before) */
.mediawiki .mw-highlight .nb {color:#2aa198;} /* text value (solid, hidden)   */
.mediawiki .mw-highlight .kc {color:#2aa198;} /* text value (rgba, hsl, url)  */
.mediawiki .mw-highlight .k  {color:#859900;} /* propertie, @-rule (@media)   */
.mediawiki .mw-highlight .kp {color:#859900;font-style:italic;} /* -webkit-   */
.mediawiki .mw-highlight .kp+.k {font-style:italic;} /* webkit propertie      */
.mediawiki .mw-highlight .mh {color:#d33682;} /* hex color (#..)              */
.mediawiki .mw-highlight .mi {color:#b58900;} /* numeric values               */
.mediawiki .mw-highlight .mf {color:#d33682;} /* decimal numeric values (0.5) */
.mediawiki .mw-highlight .kt {color:#b58900;} /* size unit (px, in)           */
.mediawiki .mw-highlight .s2 {color:#cb4b16;} /* [...="value"]                */
.mediawiki .mw-highlight .sx {color:#cb4b16;font-style:italic;} /* media link */
.mediawiki .mw-highlight .nf {color:#cb4b16;font-weight:bold;} /* --var       */

/* === Колір нумерації рядків коду під час перегляду поза редактором коду === */
.theme-fandomdesktop-dark .mw-content-ltr.mw-highlight-lines pre, .mw-content-ltr.content .mw-highlight-lines pre {
	padding-left: 3.5em;
	box-shadow: inset 2.75em 0 0 #232323;
}

/* === Профайл (змінений скрипт AdaptiveProfile) === */
/* ==== Банер ==== */
.skin-fandomdesktop #userProfileApp {
	--banner-image: url('');
	--banner-pos: center;
	--banner-ratio: ;
	--width-padding: 186px;
	margin: -24px -36px 12px -36px !important;
}

/* ==== Для UWStyle ==== */
#userProfileApp .user-identity-box,
#userProfileApp .user-identity-header__actions button {
	margin: 0;
}

/* ==== Аватар ===== */
body.skin-fandomdesktop #userProfileApp .user-identity-avatar {
	-webkit-box-sizing: content-box;
	-moz-box-sizing: content-box;
	box-sizing: content-box;
	height: 140px;
	padding: 18px 0 0 28px;
	width: 140px;
	z-index: 1;
}

#userProfileApp .user-identity-avatar__image {
	border: solid 2px var(--theme-accent-color) !important;
	-webkit-box-shadow: 0 0 10px rgb(0 0 0 / 50%);
	-moz-box-shadow: 0 0 10px rgb(0 0 0 / 50%);
	box-shadow: 0 0 10px rgb(0 0 0 / 50%);
}

/* ===== Локальний аватар ===== */
body .user-identity-avatar:before {
	background-image: var(--wiki-avatar);
	background-position: center top;
	background-size: auto 100%;
	border-radius: 50%;
	content: '';
	height: 138px;
	margin: 2px 0 0 2px;
	position: absolute;
	width: 138px;
}

/* ==== Заголовок ==== */
body.skin-fandomdesktop #userProfileApp .user-identity-header {
	background: var(--theme-accent-color);
	left: calc(var(--width-padding)*-1);
	min-height: 37px;
	padding-left: var(--width-padding);
	position: relative;
	width: calc(100% + var(--width-padding));
}

#userProfileApp .user-identity-header :is(h1,h2) {
	color: var(--theme-accent-label-color);
}

#userProfileApp .user-identity-header__attributes,
#userProfileApp .user-identity-header__action {
	align-items: center;
	display: flex;
	flex-wrap: wrap;
	grid-row-gap: 5px;
}

body.skin-fandomdesktop #userProfileApp .user-identity-header__tag {
	background-color: var(--theme-accent-color--hover);
	color: var(--theme-accent-label-color);
	margin: 6px 12px 6px 0 !important;
}

/* ==== Навігація ==== */
#userProfileApp .user-profile-navigation {
	justify-content: center;
}

/* ==== Редактор профайлу ==== */
#userProfileApp .user-identity-header__actions {
	align-items: center;
	display: flex;
}

body.skin-fandomdesktop #userProfileApp .user-identity-header__actions .wds-button,
.modal-wrapper__header .modal-wrapper__cta-button {
	border: none;
	border-radius: 18px;
	margin-right: 1em;
	color: rgb(var(--theme-accent-dynamic-color-2--rgb),.5);
	padding: .4em .8em;
}

body.skin-fandomdesktop #userProfileApp .user-identity-header__actions .wds-button:hover,
.modal-wrapper__header .modal-wrapper__cta-button:hover,
.modal-wrapper__header .wds-is-square:hover {
	background-color: rgba(var(--theme-link-color--rgb),.3);
	color: var(--theme-page-accent-mix-color) !important;
}

/* ==== Адаптація для мобільних пристроїв ==== */
@media (max-width: 713px) {
	.user-profile-navigation {
		overflow-x: scroll; white-space: nowrap;
	}
	.user-profile-navigation__link {
		width: auto !important;
	}
	.user-identity-header {
		flex-direction: column;
	}
	.user-identity-box {
		flex-direction: column;
	}
	.user-identity-avatar {
		margin: 10px auto !important;
		padding: 0 !important;
	}
	.user-identity-header {
		align-items: center;
		left: 0 !important;
		gap: 0px !important;
		padding-left: 0px !important;
		width: 100% !important;
	}
	.user-identity-box__info {
		display: flex;
		flex-direction: column;
		gap: 10px;
	}
	.user-identity-box__info > :is(ul,div:not(.user-identity-header)) {
		margin: 0 0 0 20px !important;
	}
}

/* ===== Банер ===== */
#userProfileApp:before {
	background: lightgreen;
	background-image: var(--banner-image);
	background-position: var(--banner-pos);
	background-size: cover;
	content: '';
	display: block;
	padding-bottom: var(--banner-ratio);
	width: 100%;
}

